/**
 * @summary Upload a file (multipart/form-data)
 */
export const getUploadFileUrl = () => {
  return `/api/upload`;
};

export const uploadFile = async (
  uploadFileBody: UploadFileBody,
  options?: RequestInit,
): Promise<UploadResult> => {
  const formData = new FormData();
  formData.append(`file`, uploadFileBody.file);
  if (uploadFileBody.state !== undefined) {
    formData.append(`state`, uploadFileBody.state);
  }
  if (uploadFileBody.city !== undefined) {
    formData.append(`city`, uploadFileBody.city);
  }
  if (uploadFileBody.providerName !== undefined) {
    formData.append(`providerName`, uploadFileBody.providerName);
  }
  if (uploadFileBody.sourceType !== undefined) {
    formData.append(`sourceType`, uploadFileBody.sourceType);
  }
  if (uploadFileBody.category !== undefined) {
    formData.append(`category`, uploadFileBody.category);
  }
  if (uploadFileBody.sourceUrl !== undefined) {
    formData.append(`sourceUrl`, uploadFileBody.sourceUrl);
  }
  if (uploadFileBody.notes !== undefined) {
    formData.append(`notes`, uploadFileBody.notes);
  }

  return customFetch<UploadResult>(getUploadFileUrl(), {
    ...options,
    method: "POST",
    body: formData,
  });
};

